#include "sblr_versioned_tag_coordinator.hpp"
#include "api_diagnostics.hpp"
#include <algorithm>
#include <map>
#include <mutex>
namespace scratchbird::engine::internal_api{namespace{std::mutex mu;using D=scratchbird::engine::sblr::SblrVersionedTagDescriptorV1;std::map<std::string,D>live,used;std::string key(const D&d){return{(const char*)d.body.data(),d.body.size()};}bool tag(const EngineRequestContext&c,const char*x){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),x)!=c.trace_tags.end();}EngineApiDiagnostic diag(std::string a,std::string b){return MakeEngineApiDiagnostic(std::move(a),std::move(b),{});}}
SblrVersionedTagCoordinationResult CompileSblrVersionedTagDescriptor(const EngineRequestContext&c,const std::string&n,std::uint64_t g){std::lock_guard l(mu);SblrVersionedTagCoordinationResult o;if(!tag(c,"private_versioned_tag_binder")||!c.statement_metadata_snapshot_engine_owned||n!=c.statement_uuid.canonical||!g||!tag(c,"cluster_provider_admitted")||!tag(c,"cluster_route_fence_admitted")){o.diagnostic=diag("CLUSTER.GATEWAY_CLUSTER_FALLTHROUGH_FORBIDDEN","sblr.versioned_tag.cluster_gate");return o;}o.descriptor.body[0]=1;o.descriptor.body[16]=1;for(int i=0;i<8;++i)o.descriptor.body[72+i]=(std::uint8_t)(g>>(8*i));if(scratchbird::engine::sblr::EncodeSblrVersionedTagDescriptorV1(o.descriptor).empty()){o.diagnostic=diag("SBLR.OPERAND.INVALID","sblr.versioned_tag.descriptor_invalid");return o;}live[key(o.descriptor)]=o.descriptor;o.ok=true;o.diagnostic=diag("OK","ok");return o;}
SblrVersionedTagCoordinationResult ConsumeSblrVersionedTagDescriptor(const EngineRequestContext&c,const D&x){std::lock_guard l(mu);SblrVersionedTagCoordinationResult o;auto k=key(x);if(!tag(c,"private_versioned_tag")){o.diagnostic=diag("SECURITY.ACCESS_DENIED","sblr.versioned_tag.hidden");return o;}auto i=live.find(k);if(i==live.end()){o.diagnostic=used.count(k)?diag("MGA.TRANSACTION.STALE","sblr.versioned_tag.stale"):diag("SECURITY.ACCESS_DENIED","sblr.versioned_tag.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=diag("PROCESS.CANCELLED","sblr.versioned_tag.cancelled");return o;}used[k]=x;live.erase(i);o.ok=true;o.descriptor=x;o.diagnostic=diag("OK","ok");return o;}}
